package com.projectdark.mobile;
import android.content.Context;import android.graphics.*;import com.projectdark.mobile.world.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.json.*;import java.io.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class DeathMapV220Test {
 MineTownV203Test f;Context c;
 @Before public void setup(){f=new MineTownV203Test();f.reset();c=RuntimeEnvironment.getApplication();}
 GameView lobby()throws Exception{DeathVillageV217Test old=new DeathVillageV217Test();old.f=f;old.c=c;return old.lobby();}
 @Test public void allFourRequestedBoundaryTilesEnterByActualGroundInputAndOldPortalIsGone()throws Exception{
  for(int u=8;u<=11;u++){setup();GameView v=lobby();RuntimeState s=f.field(v,"state");WorldRuntimeAdapter w=f.field(v,"poteFieldAdapter");assertTrue(CampaignNavigationTest.walk(w,w.requestGroundWorld(DeathVillageGeometry.x(u,2),DeathVillageGeometry.y(u,2))));w.tickNavigation(.7f);w.snapCameraToPlayer();WorldCameraTransform.Point p=w.worldToScreen(DeathVillageGeometry.x(u,0),DeathVillageGeometry.y(u,0));f.tap(v,p.x,p.y);for(int i=0;i<80&&DeathVillageGeometry.LOBBY.equals(s.currentMapId());i++)f.tick(v,1);assertEquals("walk into source tile "+u+",0",DeathVillageGeometry.FIELD,s.currentMapId());assertFalse((Boolean)f.call(v,"checkCampaignGate",new Class<?>[]{}));}
  DeathVillageTravel travel=new DeathVillageTravel();travel.arrived(DeathVillageGeometry.LOBBY,null);assertNull(travel.at(DeathVillageGeometry.LOBBY,DeathVillageGeometry.x(27,10),DeathVillageGeometry.y(27,10)));assertEquals(4,DeathVillageGeometry.gates(DeathVillageGeometry.LOBBY).size());
 }
 @Test public void arrivalAcrossEntireFourTilePortalCannotBounceUntilPlayerLeavesIt(){DeathVillageData.Gate back=DeathVillageGeometry.gates(DeathVillageGeometry.FIELD).stream().filter(g->g.to.equals(DeathVillageGeometry.LOBBY)).findFirst().get();DeathVillageTravel travel=new DeathVillageTravel();travel.arrived(DeathVillageGeometry.LOBBY,back);for(int u=8;u<=11;u++)assertNull(travel.at(DeathVillageGeometry.LOBBY,DeathVillageGeometry.x(u,0),DeathVillageGeometry.y(u,0)));assertNull(travel.at(DeathVillageGeometry.LOBBY,DeathVillageGeometry.x(10,5),DeathVillageGeometry.y(10,5)));assertNotNull(travel.at(DeathVillageGeometry.LOBBY,DeathVillageGeometry.x(10,0),DeathVillageGeometry.y(10,0)));}
 @Test public void everyTownMinimapOpensOriginalArtWithPinsAndReadOnlyTouchPreservesCameraAndBoundedCache()throws Exception{
  for(String id:new String[]{WorldDef.ID,AbelTownGeometry.ID,RucesionTownGeometry.ID,MineTownGeometry.ID,DeathVillageGeometry.LOBBY,DeathVillageGeometry.FIELD}){setup();GameView v=new GameView(c);v.layout(0,0,1280,540);if(!WorldDef.ID.equals(id)){if(DeathVillageGeometry.FIELD.equals(id)){f.call(v,"travelTown",new Class<?>[]{String.class},DeathVillageGeometry.LOBBY);f.call(v,"changeCampaignMap",new Class<?>[]{String.class,boolean.class},id,false);}else f.call(v,"travelTown",new Class<?>[]{String.class},id);}RuntimeState s=f.field(v,"state");WorldRuntimeAdapter w=f.field(v,WorldDef.ID.equals(id)?"worldAdapter":"poteFieldAdapter");WorldCameraTransform live=w.camera();float x=s.player().x,y=s.player().y,cx=live.cameraX(),cy=live.cameraY();long gold=s.rpg().gold();f.tap(v,68,73);WorldMapWindow map=f.field(v,"worldMap");assertTrue(map.open);assertTrue(id+" actual entrances",map.pins().size()>0);assertSame(live,w.camera());assertEquals(cx,live.cameraX(),0);assertEquals(cy,live.cameraY(),0);f.shot(v,"v220-map-"+id);f.tap(v,640,270);assertTrue("map is read only",map.open);assertEquals(x,s.player().x,0);assertEquals(y,s.player().y,0);assertEquals(gold,s.rpg().gold().longValue());int builds=map.builds();for(int i=0;i<12;i++){f.tap(v,1067,36);assertFalse(map.open);f.tap(v,68,73);assertTrue(map.open);}assertEquals(builds,map.builds());assertTrue(map.bytes()<=2097152);f.tap(v,1067,36);assertFalse(map.open);assertSame(live,w.camera());}
 }
 @Test public void recordedMonsterLooksAndActualOutdoorHouseUndergroundRostersReplaceRejectedArt()throws Exception{
  JSONObject manifest;try(InputStream in=c.getAssets().open("death-v217/manifest.json")){manifest=new JSONObject(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}int[] mpfs={166,178,175,176};for(int i=0;i<4;i++)assertEquals(mpfs[i],manifest.getJSONArray("monsters").getJSONObject(i).getInt("mpf"));assertArrayEquals(new String[]{"좀비","니크르","웨어렛","독거미"},DeathVillageMonsters.NAMES);
  GameView v=lobby();RuntimeState s=f.field(v,"state");for(String id:new String[]{DeathVillageGeometry.FIELD,"MAP_DEATH_HOUSE_1","MAP_DEATH_UNDER_C"}){f.call(v,"changeCampaignMap",new Class<?>[]{String.class,boolean.class},id,false);java.util.Set<Integer> found=new java.util.HashSet<>();for(RuntimeState.Monster m:s.monsters())found.add(DeathVillageMonsters.type(m.id));assertEquals(DeathVillageGeometry.FIELD.equals(id)?java.util.Set.of(0):DeathVillageGeometry.house(id)?java.util.Set.of(1,3):java.util.Set.of(2),found);WorldRuntimeAdapter w=f.field(v,"poteFieldAdapter");RuntimeState.Monster m=s.monsters().get(0);s.player().x=m.x-96;s.player().y=m.y-48;w.snapCameraToPlayer();f.shot(v,"v220-monsters-"+id);assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(c);GameView restored=new GameView(c);assertEquals(id,((RuntimeState)f.field(restored,"state")).currentMapId());v=restored;v.layout(0,0,960,540);s=f.field(v,"state");}
 }
}
